<script setup>
import TablePanel from '../../shared/components/TablePanel.vue';

import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {useSalesRuntime} from './sales-runtime.js';
import {copyPolicy} from './sales-model.js';
import PrintScopePicker from './PrintScopePicker.vue';
import AgentProductPicker from '../catalog/AgentProductPicker.vue';
import '../catalog/catalog.css';
import './sales.css';
import './print-scope-original.css';
const vm=useSalesRuntime(),mode=ref('general'),base=ref(null),draft=ref(null),ruleId=ref(null),ruleVersion=ref(0),name=ref(''),active=ref(true),selected=ref([]),search=ref(''),scopeKind=ref('all'),rules=ref([]),meta=reactive({current_page:1,last_page:1,total:0});
const pageSize=ref(10);
watch(pageSize,()=>loadRules());
const generalKey=vm.key(),ruleKey=vm.key(),toggleKeys=new Map();let controller;
const products=computed(()=>vm.state.options.products.map(product=>({...product,provider:product.provider_id})));
const targets=computed(()=>vm.state.options.accounts.filter(account=>account.type!=='system').flatMap(account=>account.type==='pos'?[{key:`pos:${account.id}`,kind:'pos',id:account.id,name:account.name,label:'نقطة بيع'}]:[{key:`agent:${account.id}`,kind:'agent',id:account.id,name:account.name,label:'حساب الوكيل فقط'},{key:`tree:${account.id}`,kind:'tree',id:account.id,name:account.name,label:'الوكيل وجميع تابعيه'}]));
const shownTargets=computed(()=>targets.value.filter(target=>(scopeKind.value==='all'||target.kind===scopeKind.value)&&target.name.toLocaleLowerCase('ar').includes(search.value.trim().toLocaleLowerCase('ar'))));
const labels={failed_retries:'محاولات إعادة الطباعة',max_cards:'بطاقات الطلب الواحد',interval_seconds:'الفاصل بين الطباعات (ثانية)',daily_cards:'البطاقات اليومية (0 بلا حد)'};
async function loadRules(page=1){try{const response=await vm.api.list('print-rules',{page,per_page:pageSize.value},controller?.signal);rules.value=response.data;Object.assign(meta,response.meta);}catch(error){if(error.name!=='AbortError')vm.state.error=await vm.failure(error);}}
async function load(){controller?.abort();controller=new AbortController();await vm.load(true);try{base.value=(await vm.api.policy(controller.signal)).data;draft.value=copyPolicy(base.value.policy);await loadRules();}catch(error){if(error.name!=='AbortError')vm.state.error=await vm.failure(error);}}
function fresh(){if(!base.value)return;mode.value='custom';ruleId.value=null;ruleVersion.value=0;name.value='';active.value=true;selected.value=[];draft.value=copyPolicy(base.value.policy);}
function edit(rule){mode.value='custom';ruleId.value=rule.id;ruleVersion.value=rule.version;name.value=rule.name;active.value=rule.active;selected.value=rule.targets.map(target=>`${target.kind}:${target.id}`);draft.value=copyPolicy(rule.policy);vm.state.error='';}
function targetNames(rule){return rule.targets.map(target=>targets.value.find(row=>row.key===`${target.kind}:${target.id}`)?.name || `#${target.id}`).join(' · ');}
async function save(){if(!draft.value)return;const policy=copyPolicy(draft.value);policy.daily_products=policy.daily_product_mode==='all'?[]:policy.daily_products.map(Number);
  if(mode.value==='general'){const response=await vm.execute({version:base.value.version,policy},generalKey,(payload,signal)=>vm.api.savePolicy(payload,signal),'تم حفظ ضوابط الطباعة.');if(response){base.value=response;draft.value=copyPolicy(response.policy);}}
  else{const selectedSet=new Set(selected.value);const payload={version:ruleVersion.value,name:name.value.trim(),active:active.value,targets:targets.value.filter(target=>selectedSet.has(target.key)).map(({kind,id})=>({kind,id})),policy};const response=await vm.execute(payload,ruleKey,(value,signal)=>vm.api.saveRule(ruleId.value,value,signal),'تم حفظ قاعدة الطباعة.');if(response){edit(response);await loadRules(meta.current_page);}}
}
async function toggle(rule){if(!toggleKeys.has(rule.id))toggleKeys.set(rule.id,vm.key());const result=await vm.execute({version:rule.version,name:rule.name,targets:rule.targets,policy:copyPolicy(rule.policy),active:!rule.active},toggleKeys.get(rule.id),(payload,signal)=>vm.api.saveRule(rule.id,payload,signal),rule.active?'تم تعطيل القاعدة.':'تم تفعيل القاعدة.');if(result)await loadRules(meta.current_page);}
watch(mode,value=>{if(value==='general'&&base.value)draft.value=copyPolicy(base.value.policy);});
onMounted(load);onBeforeUnmount(()=>{controller?.abort();toggleKeys.clear();});
</script>
<template><div class="catalog-workspace sales-workspace"><p v-if="vm.state.error" class="notice warn" role="alert">{{vm.state.error}}</p><p v-if="vm.state.notice" class="notice" role="status">{{vm.state.notice}}</p><section class="card print-policy-settings"><form v-if="draft" @submit.prevent="save"><fieldset :disabled="vm.state.busy || !vm.can('security.policies')" class="sales-fieldset"><div class="print-policy-header print-policy-inline" :class="{'is-custom':mode==='custom'}"><h3>ضوابط الطباعة</h3><div class="print-policy-modes" role="group" aria-label="نطاق الإعدادات"><button type="button" :class="{active:mode==='general'}" :aria-pressed="mode==='general'" @click="mode='general'">عام</button><button type="button" :class="{active:mode==='custom'}" :aria-pressed="mode==='custom'" @click="mode!=='custom' && fresh()">مخصص</button></div><label v-if="mode==='custom'" class="print-policy-name"><span>اسم القاعدة</span><input v-model="name" placeholder="مثال: طباعة فروع بغداد" maxlength="160" required></label><label v-for="(label,key) in labels" :key="key" class="print-policy-number"><span>{{label}}</span><input v-model.number="draft[key]" type="number" :min="key==='max_cards'?1:0" step="1" required></label><label class="print-policy-number"><span>احتساب الحد اليومي</span><select v-model="draft.daily_mode"><option value="account">لكل حساب مستقلاً</option><option value="network">مجموع شبكة كل وكيل</option></select></label><div class="print-policy-inline-actions"><button class="btn primary">حفظ ضوابط الطباعة</button></div><select v-if="meta.total" v-model.number="pageSize" aria-label="عدد نطاقات الطباعة في الصفحة"><option v-for="size in [10,25,50,100]" :value="size">{{size}}</option></select></div><div v-if="mode==='custom'" class="formgrid"><label>نطاق الفئات<select v-model="draft.daily_product_mode"><option value="all">كل الفئات — مجموع مشترك</option><option value="selected">فئات محددة — حد مستقل لكل فئة</option></select></label></div><AgentProductPicker v-if="mode==='custom' && draft.daily_product_mode==='selected'" v-model="draft.daily_products" :products="products"/><template v-if="mode==='custom'"><PrintScopePicker v-model="selected" :accounts="vm.state.options.accounts"/></template></fieldset></form><p v-else class="empty">{{vm.state.loading?'جارٍ تحميل ضوابط الطباعة…':'ضوابط الطباعة غير متاحة'}}</p><h3>النطاقات المحفوظة</h3><TablePanel class="tablewrap"><table><thead><tr><th>القاعدة / النطاق</th><th>محاولات الفشل</th><th>بطاقات الطلب</th><th>الفاصل بالثواني</th><th>الحد اليومي</th><th>الفئات</th><th>الاحتساب</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="rule in rules" :key="rule.id"><td><b>{{rule.name}}</b><div class="caption">{{targetNames(rule)}}</div></td><td>{{rule.policy.failed_retries}}</td><td>{{rule.policy.max_cards}}</td><td>{{rule.policy.interval_seconds}}</td><td>{{rule.policy.daily_cards || 'بلا حد'}}</td><td>{{rule.policy.daily_product_mode==='selected'?`حد مستقل لكل فئة (${rule.policy.daily_products.length})`:'كل الفئات — مجموع مشترك'}}</td><td>{{rule.policy.daily_mode==='network'?'مجموع شبكة كل وكيل':'لكل حساب'}}</td><td>{{rule.active?'فعال':'معطل'}}</td><td><div class="actions"><button type="button" class="btn small" :disabled="vm.state.busy" @click="edit(rule)">تعديل</button><button type="button" class="btn small" :disabled="vm.state.busy" @click="toggle(rule)">{{rule.active?'تعطيل':'تفعيل'}}</button></div></td></tr></tbody></table></TablePanel><div v-if="meta.total" class="sales-pagination"><button type="button" class="btn small" :disabled="meta.current_page<=1" @click="loadRules(meta.current_page-1)">السابق</button><span>{{meta.current_page}} / {{meta.last_page}}</span><button type="button" class="btn small" :disabled="meta.current_page>=meta.last_page" @click="loadRules(meta.current_page+1)">التالي</button></div></section></div></template>

<style scoped>
.print-policy-inline{background:var(--raised);border:1px solid var(--line);border-radius:12px;margin-bottom:0}
.sales-workspace .print-policy-header{gap:10px;flex-wrap:nowrap;overflow-x:auto}.sales-workspace .print-policy-header.is-custom .print-policy-inline-actions{order:9}.sales-workspace .print-policy-header.is-custom{align-items:end}.sales-workspace .print-policy-name{flex:0 0 125px;min-width:125px}.sales-workspace .print-policy-header h3,.sales-workspace .print-policy-modes{flex-shrink:0}.sales-workspace .print-scope-picker{margin-top:18px}.sales-workspace .scope-choice-main input{flex:none;width:18px;min-height:18px}.sales-workspace .scope-selected-filter input{width:18px;min-height:18px}
.sales-workspace .print-policy-number{min-width:110px;flex:0 0 110px}
.sales-workspace .print-policy-header h3{white-space:nowrap;font-size:15px}
.sales-workspace .print-policy-modes button.active{background:#089bb6}
.print-policy-modes{background:var(--raised)!important}.print-policy-modes button{min-width:58px}.print-policy-inline>select{width:70px;flex:none}
.sales-workspace .print-policy-header label>input,.sales-workspace .print-policy-header label>select,.sales-workspace .print-policy-inline-actions .btn{height:44px;min-height:44px}
@media(max-width:900px){.sales-workspace .print-policy-header{flex-wrap:wrap}.sales-workspace .print-policy-number{min-width:90px}}
</style>
